function diffFrontmatter(l, attrsB) {
  const changes = {}
  const allKeys = new Set([...Object.keys(l), ...Object.keys(attrsB)])

  for (const key of allKeys) {
    const valA = l[key]
    const valB = attrsB[key]
    if (JSON.stringify(valA) !== JSON.stringify(valB)) {
      changes[key] = { from: valA, to: valB }
    }
  }

  return changes
}
